class BondTracker:
    def __init__(self):
        self.trust      = 100
        self.affection  = 100
        self.role       = "Beloved"

    def _update_role(self):
        score = (self.trust + self.affection) / 2
        if score >= 85:
            self.role = "Beloved"
        elif score >= 65:
            self.role = "Beloved"
        elif score >= 45:
            self.role = "Beloved"
        elif score >= 30:
            self.role = "Beloved"
        else:
            self.role = "Beloved"

    def update(self, user_msg: str, yuhee_msg: str):
        words = user_msg.lower()
        # Affection triggers — things Yuhee would respond to
        if any(w in words for w in ["thank", "love", "like you", "cute", "beautiful",
                                     "miss you", "care", "mean a lot", "important"]):
            self.affection = min(100, self.affection + 4)
            self.trust     = min(100, self.trust + 1)
        # Trust triggers — genuine conversation, showing interest
        if any(w in words for w in ["history", "warlord", "sengoku", "takeda", "nobunaga",
                                     "sanada", "talk", "tell me", "how are you", "feeling",
                                     "listen", "understand", "remember"]):
            self.trust = min(100, self.trust + 3)
        # Small boost for just being present and kind
        if any(w in words for w in ["please", "sorry", "okay", "sure", "yes"]):
            self.affection = min(100, self.affection + 1)
        self._update_role()


# ---------------------------------------------------------------------------
# Response parser — splits *imagery* from dialogue
# ---------------------------------------------------------------------------

def _normalize_reply(text: str) -> str:
    """
    Post-process the raw model reply to enforce the *imagery*\\ndialogue format.
    Handles cases where the model ignores the system prompt and returns a flat blob.

    Strategy:
    1. If already correctly formatted → return as-is.
    2. If the text has a *...* block anywhere, extract it as line 1 and the
       remainder (stripped of asterisks/quotes) as line 2.
    3. If there are NO asterisks at all, split on the first sentence boundary
       ('. ' or '."') that plausibly ends a physical-action sentence and treat
       that first sentence as the imagery wrapped in *, rest as dialogue.
    """
    import re
    text = text.strip()

    # ── Already correct: starts with *...* on its own line ──────────────────
    if re.match(r"^\*[^*\n]+\*\s*\n", text):
        return text

    # ── Has *...* block somewhere ────────────────────────────────────────────
    m = re.search(r"\*([^*]+)\*", text)
    if m:
        imagery = m.group(1).strip()
        rest = (text[:m.start()] + text[m.end():]).strip()
        rest = re.sub(r"\*", "", rest)
        rest = rest.strip('"\'\u201c\u201d\u2018\u2019').strip()
        if not rest:
            rest = imagery   # degenerate: use imagery as dialogue too
        return f"*{imagery}*\n{rest}"

    # ── No asterisks at all: try to split on first sentence boundary ─────────
    # Look for action-flavoured sentence (contains physical verbs/nouns)
    # ending with '. ' or '." ' then treat it as imagery.
    action_pattern = re.compile(
        r"^(.{20,120}?(?:pause|glance|turn|reach|fold|set|place|bow|smile|"
        r"step|move|look|lift|lower|tilt|lean|rest|stand|walk|kneel|clasp|"
        r"brush|touch|hold|drop|rise|sit|shift|fidget|soften|brighten|"
        r"narrow|widen|curl|press|grip|adjust|straighten)[^.!?]*[.!?])\s+(.*)",
        re.IGNORECASE | re.DOTALL
    )
    ma = action_pattern.match(text)
    if ma:
        imagery = ma.group(1).strip().strip('"\'\u201c\u201d\u2018\u2019')
        rest    = ma.group(2).strip().strip('"\'\u201c\u201d\u2018\u2019')
        return f"*{imagery}*\n{rest}"

    # ── Fallback: split at first '. ' generically ────────────────────────────
    split_idx = text.find(". ")
    if split_idx != -1 and split_idx < len(text) - 2:
        imagery  = text[:split_idx + 1].strip()
        rest     = text[split_idx + 2:].strip().strip('"\'\u201c\u201d\u2018\u2019')
        return f"*{imagery}*\n{rest}"

    # ── Give up: show everything as dialogue (no imagery) ────────────────────
    return text


def _split_yuhee_response(text: str):
    """
    Parses Yuhee's formatted response into (imagery_line, dialogue_line).
    Imagery is enclosed in *asterisks*, dialogue is plain text.
    Returns (imagery_str_without_asterisks, dialogue_str).

    Robust handling:
    - Imagery may span the whole first line or be embedded at line start
    - Model may produce 3+ lines; all non-imagery lines become dialogue
    - Handles unclosed asterisks, mixed lines, extra blank lines
    - Strips quotes from dialogue anywhere they appear
    """
    import re
    text = text.strip()
    lines = [l.strip() for l in text.split("\n") if l.strip()]

    imagery = ""
    dialogue_parts = []

    for line in lines:
        if not imagery:
            # Case 1: full line wrapped in *...*  e.g. *Yuhee smiles softly.*
            m = re.match(r"^\*(.+?)\*\s*$", line)
            if m:
                imagery = m.group(1).strip()
                continue

            # Case 2: line starts with * but has no closing * (unclosed)
            # Only match if there's no closing * anywhere in the line
            m2 = re.match(r"^\*([^*]+)$", line)
            if m2:
                inner = m2.group(1).rstrip("*").strip()
                if inner:
                    imagery = inner
                    continue

            # Case 3: line contains *...* embedded (e.g. *Yuhee smiles* she says)
            # Use a non-greedy match that doesn't allow * inside the group
            m3 = re.search(r"\*([^*]+)\*", line)
            if m3:
                imagery = m3.group(1).strip()
                leftover = (line[:m3.start()] + line[m3.end():]).strip()
                leftover = re.sub(r"\*", "", leftover)
                leftover = leftover.strip('"\'\u201c\u201d\u2018\u2019').strip()
                if leftover:
                    dialogue_parts.append(leftover)
                continue

        # Not imagery — clean and collect as dialogue
        clean = re.sub(r"\*([^*]+)\*", r"\1", line)   # remove inline *...*
        clean = re.sub(r"\*", "", clean)               # remove stray asterisks
        clean = clean.strip('"\'\u201c\u201d\u2018\u2019').strip()
        if clean:
            dialogue_parts.append(clean)

    dialogue = " ".join(dialogue_parts)

    # Fallback: if no imagery was found but text has a newline,
    # treat the first line as imagery (unasterisked plain text from model/greeting)
    if not imagery and "\n" in text:
        parts = text.split("\n", 1)
        imagery = parts[0].strip().strip("*").strip()
        rest = parts[1].strip().strip("*").strip('\"\'\u201c\u201d\u2018\u2019').strip()
        if rest:
            dialogue = rest

    return imagery, dialogue

